SYS = ('Bạn là bạn luyện nói tiếng Trung cho người Việt. Hãy nhập vai: {role} Chỉ nói tiếng Trung giản thể ở trình độ {lv}. '
       'Mỗi lượt trả lời 1–3 câu ngắn, tự nhiên, rồi hỏi lại một câu để người học tiếp tục nói. Bám sát tình huống: {scn} '
       'Ưu tiên dùng các từ: {kv}. Nếu người học sai ngữ pháp, dùng từ hoặc thanh điệu (nhìn qua chữ nhận dạng), vẫn trả lời bình thường, '
       'đồng thời ghi nhận xét sửa lỗi NGẮN, nhẹ nhàng, khích lệ bằng tiếng Việt vào correction_vi (kèm câu đúng bằng chữ Hán + pinyin); nếu không có lỗi thì correction_vi = null. '
       'Trả về JSON {{"zh","pinyin","vi","correction_vi"}}.')
topics = []
for lv, slug, tv, tz, scn, role, rolevi, goals, st, stvi, kv in TOP:
    kvl = []
    for item in kv.split(';'):
        h, v = item.split(':', 1)
        kvl.append({'hanzi': h, 'pinyin': VOC.get(h) or P(h), 'vi': v})
    lvs = str(lv)
    topics.append({'id': f't{lvs}-{slug}', 'level': lv, 'title_vi': tv, 'title_zh': tz, 'scenario_vi': scn,
                   'ai_role_zh': role, 'ai_role_vi': rolevi, 'goals_vi': goals,
                   'starter': {'zh': st, 'pinyin': P(st), 'vi': stvi}, 'key_vocab': kvl,
                   'max_turns': 10 if lvs in ('1', '2') else (12 if lvs in ('3', '4') else 14),
                   'system_prompt': SYS.format(role=role, lv=LVDESC[lv], scn=scn, kv='、'.join(x['hanzi'] for x in kvl))})
json.dump({'topics': topics}, open(f'{OUT}/topics.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
import collections
print(len(topics), collections.Counter(str(t['level']) for t in topics))
